@Configuration
public class CuadreCifrasJobConfig {

    /** 00000000-PRINCIPAL: librerías, apertura, procesos y cierre. */
    @Bean
    Job cuadreCifrasCaptacion(JobRepository repo,
                              Step candadosArranque,     // 10000000-LIBRERIAS + 20000000-OPEN
                              Step cuadreCifras,         // 50005000-IMP-CIFRAS (lee B09)
                              Step ordenaTotCve,         // 50006000-SORT-CVES
                              Step cuadrePorClave,       // 50007000-LEO-TOTCVE
                              Step cierre) {             // 70000000-CIERRO: B02, B00, FINBATCH S151
        return new JobBuilder("S500P170", repo)
                .start(candadosArranque)
                .next(cuadreCifras)
                .next(ordenaTotCve)
                .next(cuadrePorClave)
                .next(cierre)
                .build();
    }
}

@Component
@RequiredArgsConstructor
public class CandadosArranqueTasklet implements Tasklet {

    private final MaestroVersiones versiones;      // S100VERSIONES
    private final LineaCreditoClient s408;         // reemplaza XATMI + LINCRED
    private final BuildProperties build;

    @Override
    public RepeatStatus execute(StepContribution c, ChunkContext ctx) {
        // 20000010-CHECO-VER
        if (!versiones.autorizada("S500P170", build.getVersion())) {
            throw new ProcesoAbortadoException("VER. EJECUTADA DIF. A VERSIONES");   // STATUS := -1
        }
        // 20000015-TRANSIT: TP_IDENTIFY("S500P170") se vuelve el handshake del cliente.
        int rslt = s408.identifica("S500P170");
        if (rslt != 0) {
            throw new ProcesoAbortadoException("ERROR EN TP_IDENTIFY " + rslt);
        }
        validaPasoAnterior();                       // 20000150-VAL-PASO
        return RepeatStatus.FINISHED;
    }
}

private final ControlPasoRepository controlPaso;   // S500B00CTRLPASO
private static final int PASO_PREVIO = 160;

@Transactional                                     // BEGIN-TRANSACTION .. END-TRANSACTIONSYNC
void validaPasoAnterior() {
    ControlPaso cp = controlPaso.findForUpdate()   // B00CTRLPASO-LOCK
            .orElseThrow(() -> new ProcesoAbortadoException("ERROR B00CTRLPASO VACIO"));
    if (cp.paso01() != PASO_PREVIO || cp.paso02() != PASO_PREVIO || cp.paso03() != PASO_PREVIO) {
        throw new ProcesoAbortadoException("ERROR BASE NO ES SALIDA DEL P160");   // DMTERMINATE
    }
    cp.reiniciaPasos();                            // MOVE 0 TO B00-NUM-PASO-01..03
    controlPaso.save(cp);                          // B00CTRLPASO-STORE
}

@Service
@RequiredArgsConstructor
public class ConsultaTotalesS408 {

    private final LineaCreditoClient s408;
    private final P170Properties props;

    public TotalesS408 consulta(CifraControl b09, LocalDate fechaProceso) {
        var req = new ConsultaTotalesRequest(
                props.s408().funcion(),          // 13
                props.s408().paso(),             // 170
                props.s408().tipoProceso(),      // 30
                fechaProceso,
                b09.producto(), b09.instrumento(), b09.moneda());
        return s408.totales(req);                // 40000200-CALL-S408 con reintentos
    }
}

